          "Step 4: Sum all results from Steps 1-3. Note: This includes potential profit from production/transit."
        ]
      },
      "livree_non_encaissee_global": {
        "formula": "sum(Gros.profit_LNE) + sum(Siteweb.profit_LNE) + sum(Merch.profit_LNE)",
