      "tresorerie_nette_finale": {
        "formula": "encaisse_reel + net_offres - total_charges - total_marketing_spend",
        "profit_source": "ENCAISSE REALIZED ONLY (LIVREE_ENCAISSE / LIVREE status)",
        "deductions": {
          "marketing_spend": "Sum of all marketing_spends.amount in period.",
          "charges_fixes": "Sum of all charges.montant in period.",
          "solde_offres": "Revenue minus Expense from the Offres module."
        }
      }
