    "vendeurs_statuses": ["livrée", "livrée_non_encaissée", "en_livraison", "retour"],
    "merch_statuses": ["en_livraison", "livree_non_encaissee", "livree", "retour"],
    "which_statuses_contribute_to_profit_real": {
      "gros": ["livree_encaisse"],
      "vendeurs": ["livrée"],
      "merch": ["livree"]
    },
    "which_statuses_contribute_to_profit_accrued": {
      "gros": ["en_production", "en_livraison", "livree_non_encaisse", "livree_encaisse"],
      "vendeurs": ["livrée", "livrée_non_encaissée", "en_livraison"],
      "merch": ["en_livraison", "livree_non_encaissee", "livree"]
    }
  },
  "data_flow": {
    "database_to_store": "Supabase real-time subscription (merchdz_realtime) triggers fetchAllData() which updates React state.",
    "store_to_dashboard": "Dashboard calls getDashboardData() which computes aggregations on current state filtered by global date range.",
    "real_time_sync": "Updates occur on any Postgres CHANGE event after a 750ms debounce."
  },
  "potential_issues_observed": [
    "Inconsistency in metric naming: 'Profit Brut Global' in Dashboard.tsx includes theoretical profit (En Livraison), while 'Trésorerie Nette Finale' is strictly cash-based.",
    "Vendor commissions are subtracted from the item profit_net in store.tsx, meaning company profit always excludes commissions correctly, but there is no separate top-level Gross Revenue (before commission) KPI in the main dashboard.",
    "Return losses are calculated as COGS (Production Cost) in Gros and Vendeurs, but as 'Prix Achat' in Merch, which is consistent but uses different naming conventions.",
    "The Dashboard.tsx KPI row re-implements calculation logic for totalProfitNet instead of using a centralized selector from store.tsx, increasing the risk of calculation drift."
  ]
}

